CREATE TABLE commerce.paper_receipt_evidence (paper_receipt_evidence_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES commerce."order"(order_id), receipt_reference text NOT NULL, payment_channel text NOT NULL, payment_namespace text NOT NULL, amount numeric(18,2) NOT NULL CHECK(amount >= 0), currency text NOT NULL, received_at timestamptz NOT NULL, evidence_document_ref text NULL, note varchar(500) NULL, entered_by uuid NOT NULL, confirmed_by uuid NULL, confirmation_at timestamptz NULL, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT paper_receipt_confirmation_fields CHECK ((confirmed_by IS NULL AND confirmation_at IS NULL) OR (confirmed_by IS NOT NULL AND confirmation_at IS NOT NULL)), UNIQUE(receipt_reference,payment_channel,payment_namespace)); CREATE INDEX paper_receipt_evidence_order_received_idx ON commerce.paper_receipt_evidence(order_id,received_at);
